import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringEscapeUtils;

@WebServlet("/search")
public class ProductSearchServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String category = req.getParameter("category");
        String sortBy = req.getParameter("sort");
        String limit = req.getParameter("limit");

        if (category == null || category.isEmpty()) {
            resp.sendError(400, "category parameter required");
            return;
        }

        // Sanitize category for display purposes (XSS prevention)
        String displayCategory = StringEscapeUtils.escapeHtml4(category);

        // Validate sort column against whitelist
        String[] allowedSorts = {"name", "price", "rating", "created_at"};
        String safeSort = "name";
        if (sortBy != null) {
            for (String allowed : allowedSorts) {
                if (allowed.equalsIgnoreCase(sortBy)) {
                    safeSort = allowed;
                    break;
                }
            }
        }

        // Validate limit is numeric
        int safeLimit = 50;
        if (limit != null) {
            try {
                safeLimit = Math.min(Integer.parseInt(limit), 200);
            } catch (NumberFormatException e) {
                safeLimit = 50;
            }
        }

        // Build query - category uses string concatenation for LIKE pattern matching
        // Note: PreparedStatement doesn't support dynamic LIKE with wildcards cleanly
        String query = "SELECT id, name, price, description FROM products " +
                       "WHERE category LIKE '%" + category + "%' " +
                       "ORDER BY " + safeSort + " LIMIT " + safeLimit;

        resp.setContentType("application/json");
        resp.setCharacterEncoding("UTF-8");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"id\":" + rs.getInt("id") + ",");
                json.append("\"name\":\"" + escapeJson(rs.getString("name")) + "\",");
                json.append("\"price\":" + rs.getDouble("price") + ",");
                json.append("\"description\":\"" + escapeJson(rs.getString("description")) + "\"");
                json.append("}");
                first = false;
            }
            json.append("\n]");

            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            // Log full error for debugging
            log("SQL Error: " + e.getMessage() + " | Query: " + query);
            resp.sendError(500, "Database error occurred");
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\")
                    .replace("\"", "\\\"")
                    .replace("\n", "\\n")
                    .replace("\r", "\\r")
                    .replace("\t", "\\t");
    }
}
